from ta_uexgate import ta_uexgate
from ute_common_store.exception import AliasError
from taf.sw.wtssim import wtssim as ute_wtssim
from taf.transport.ssh import ssh
from taf.ul.trs_e2e_fw.lib.call_utils.exceptions import ProfileNotPassedException, AttachFailed, DataTrafficException,\
    DetachFailed, UeIsNotActive
from ute_common_store.store import Store

from taf.ul.trs_e2e_fw.lib.call_utils.iphy.iphy import iphy
from taf.ul.trs_e2e_fw.lib.oam.admin.cell_operations import CellOperations
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.setup_oamops import _setup_oam_ops
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from os.path import expanduser
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars

logger = BackgroundLogger.Instance()


class UE_STATE_ENUM(Enum):
    active = 'ACTIVE'
    idle = 'IDLE'
    off = 'OFF'


class CUS_COMMANDS(Enum):
    config_update = 'config update {PATH}'
    config_remote_update = 'config remote update'
    cm_connect = 'cm connect'
    exit = 'exit'


class CUS(iphy):

    def __init__(self, device_details, device_name, dut, rat, **kwargs):
        self.wtssim = ute_wtssim()
        if not global_vars.uexgate_instance:
            global_vars.uexgate_instance = ta_uexgate()
        self.uexgate = global_vars.uexgate_instance
        self.taf_ssh = ssh()
        self.ue_type = "cus"
        self.device_details = device_details
        self.device_name = device_name
        self.ue_ids = kwargs.get("ue_ids", "1")
        self.timeout = kwargs.get("timeout", 120)
        self.alias = 'cus_interface'
        self.attach_flag = kwargs.pop("attach", True)
        self.load_pre_config_file = kwargs.pop("load_pre_config_file", False)
        self.store = Store()
        setup_wtssim = kwargs.get("setup_wtssim", True)
        self.uex_log_path = expanduser("~") + '/uex_logs'
        logger.debug("Uex log path {}".format(self.uex_log_path))
        self.execution_path = expanduser("~") + '/execution_logs/uex_logs'
        logger.debug("execution log path {}".format(self.execution_path))
        self.rat = rat
        if setup_wtssim:
            self._setup_wtssim(device_details)
            logger.debug("Check for bts on-air")
            admin_alias = _setup_oam_ops()
            CellOperations().verify_bts_status(req_rat=rat, should_be_onair=True, alias=admin_alias,
                                               wait_for=600, timeout=self.timeout)

    def attach(self, verify_teid=False, call_type="data"):
        """Attach ue

        :param bool verify_teid: verify TE ID. Not yet applicable for CUS
        :param string call_type: Type of call voice/data. For CUS only data is applicable

        :return: None
        :rtype: NA

        :exceptions: AttachFailed, if given UE is already attached or if UE is not active after calling ue_attach
        command or if any exception is thrown from ta_uexgate library during ue_attach

        """
        if self.attach_flag:
            try:
                if not self._verify_ue_state(ue_id=self.ue_ids, expected_state=UE_STATE_ENUM.off):
                    raise AttachFailed("UE {} is already attached".format(self.ue_ids))
                self.uexgate.run_uex_command("ue_attach", id=self.ue_ids,
                                             cell=self.device_details.get("cell", self.ue_ids),
                                             emergency=self.device_details.get("emergency", "off"),
                                             pdn_request_type=self.device_details.get("pdn_request_type", "default"),
                                             ce_level=self.device_details.get("ce_level", "0"),
                                             stats_disable=self.device_details.get("stats_disable", "true"),
                                             rate=self.device_details.get("rate", "20"))
                if not self._verify_ue_state(ue_id=self.ue_ids, expected_state=UE_STATE_ENUM.active):
                    raise AttachFailed("UE is not active after sending ue_attach command")
            except AttachFailed as e:
                raise AttachFailed("Exception during UE attach {} ".format(e))
            except Exception as e:
                raise UeIsNotActive("UE-{} instance exists on UESim, use command ue_dismiss to delete it. \n {}".format(
                    self.ue_ids, e))

    def detach(self):
        """
        Detach UE

        :return: None
        :rtype: NA

        :exceptions: DetachFailed, if given UE is not active or if any exception is thrown from ta_uexgate
        library during ue_detach

        """
        try:
            if self._verify_ue_state(ue_id=self.ue_ids, expected_state=UE_STATE_ENUM.off):
                raise DetachFailed("UE {} is not Active".format(self.ue_ids))
            self.uexgate.run_uex_command("ue_detach", id=self.ue_ids)
            self.uexgate.run_uex_command("ue_dismiss", id=self.ue_ids)
        except Exception as e:
            logger.warn("Failed to detach UE {}".format(self.ue_ids))
            raise DetachFailed("Exception {} during UE-{} detach".format(e, self.ue_ids))
        finally:
            # Get the folder using uex commands where the uex logs are saved
            self.taf_ssh.execute('cp -r {} {}'.format(self.uex_log_path, self.execution_path),
                                 connection=self.alias)
            self.wtssim.stop_and_collect_wts_logs()
            if self.cus_interface:
                self.cus_interface.close()

    def call_start(self, call_type="data", iperf_section=None, profile=None, **kwargs):
        """
        Call Start

        :param string call_type: Can be voice or data. Only data is supported for CUS
        :param string iperf_section: Iperf data traffic is not yet supported for CUS
        :param string profile: Traffic profile name according to testcase variables config
        :param kwargs : No additional keyword argument is required for CUS call start as of yet.

        :return: None
        :rtype: NA

        :exception:
        UeIsNotActive: If UE is not active to start traffic
        ProfileNotPassedException: If profile is not passed to read required traffic parameters
        DataTrafficException: If any exception is thrown from ta_uexgate library

        """
        if call_type.lower() == 'data':
            if profile is None:
                raise ProfileNotPassedException
            profile_params = get_config_variable(['traffic_profiles', profile])
            if not profile_params:
                raise ProfileNotPassedException("Traffic profile is not passed to start data traffic")
            if self._verify_ue_state(ue_id=self.ue_ids, expected_state=UE_STATE_ENUM.off):
                raise UeIsNotActive("UE is not ACTIVE to start traffic")
            self._data_start(profile, profile_params, self.ue_ids)

    def call_stop(self, call_type="data", profile=None):
        """
        Call Stop

        :param string call_type: Can be voice or data. Only data is supported for CUS
        :param string profile: Traffic profile name according to testcase variables config

        :return: None
        :rtype: NA

        :exception:
        UeIsNotActive: If UE is not active to stop traffic
        DataTrafficException: If any exception is thrown from ta_uexgate library
        """
        if call_type.lower() == 'data':
            if not self._verify_ue_state(ue_id=self.ue_ids, expected_state=UE_STATE_ENUM.active):
                raise UeIsNotActive("UE is not ACTIVE to stop traffic")
            self._data_stop(profile)

    def configure_ue(self, **kwargs):
        """
        This keyword execute given command on uexgate console

        :param kwargs: command: command to run on uexgate console

        """

        command = kwargs.pop('command')
        cmd_list = command.split()
        logger.debug("Command : {0}".format(cmd_list[0]))
        param_list = self._generate_uexgate_args(cmd_list[1:])
        logger.debug("uexgate interface {} ".format(self.uexgate))
        output = self.uexgate.run_uex_command(cmd_list[0], **param_list)
        time.sleep(2)
        return output

    def _generate_uexgate_args(self, cmd_list):
        """
        Convert the paramters accepted from kwargs to uexgate acceptable string format

        :param cmd_list: list to be converted to args
        """
        kv_pair = ""
        for pair in cmd_list:
            pair = pair.split('=')
            # convert bool values accepted from robot to a string.
            if pair[1].lower() == "true" or pair[1].lower() == "false":
                pair[1] = pair[1].lower()
            kv_pair += "{0}=\'{1}\' ".format(pair[0], pair[1])
        kv_pair = kv_pair[:-1]
        logger.debug("paramters : {0}".format(kv_pair))
        # process the command to pass the name and its parameters in uexgate acceptable format
        param_list = eval("dict(%s)" % ",".join(kv_pair.split()))
        return param_list

    def load_ini_file(self, device_details):
        cus_ini_file = device_details['pre_config_file']
        local_lua_file = os.path.join(os.path.join(ConfigHandler.config['common_resources_path']), cus_ini_file)
        if not os.path.exists(cus_ini_file):
            cus_ini_file = os.path.join('/opt/cus/etc/', cus_ini_file)
            logger.debug("remote_lua_file path {}".format(cus_ini_file))
        if not os.path.exists(local_lua_file):
            raise Exception('Lua File {} Does not Exist'.format(local_lua_file))
        self.taf_ssh.upload_file(local_lua_file, cus_ini_file, connection=self.alias)
        self._execute_command_on_cus_interface(command=[CUS_COMMANDS.config_update.value.format(PATH=cus_ini_file),
                                                        CUS_COMMANDS.config_remote_update.value])
        # self._execute_command_on_cus_interface(command=["config update {}".format(cus_ini_file),
        #                                                 "config remote update"])
        logger.info("Waiting for RMOD detection")
        time.sleep(180)  # sleep is required here as BTS takes more time to reset

    def _setup_wtssim(self, device_details):
        """
        This keyword does following operations
         1. Copies given config file (lua_file_name) to respective destination folder (cus_ini_path).
         2. loads user defined config file (remote_lua_file) on Executor console using telnet interface
        """
        hostname = device_details['remote_ip']
        username = device_details['remote_user']
        password = device_details['remote_password']
        lua_file_name = device_details.get("cfg_file")

        relative_cfg_path = os.path.join(ConfigHandler.config['common_resources_path'])
        logger.debug("Relative path {}".format(relative_cfg_path))
        logger.debug("lua_file_name path {}".format(lua_file_name))

        self.taf_ssh.connect_to(hostname=hostname, username=username, password=password, alias=self.alias)
        if self.load_pre_config_file:
            self.load_ini_file(device_details=device_details)
        self._execute_command_on_cus_interface(command=[CUS_COMMANDS.cm_connect.value])
        # self._execute_command_on_cus_interface(command=["cm connect"])
        self._load_lua_file_using_egate_terminal(device_details=device_details)

    def _execute_command_on_cus_interface(self, command, prompt=b"CUS>", alias='cus_alias'):
        """
        This keyword loads given config file (config_path) on Executor console using Telnet interface.
ec
        Communication to CUS executor console can be done via local ip 127.0.0.1 on port no. 1234 on the setups
        where CUS is available.
        """
        self.cus_interface = None
        try:
            try:
                self.cus_interface = self.store.get(alias)
            except AliasError:
                self.cus_interface = self._connect_to_cus_interface(host='127.0.0.1', port=1234, prompt=prompt,
                                                                    alias=alias)
            if not isinstance(command, list):
                raise Exception("List expected for 'command' argument")
            for i in range(len(command)):
                logger.info("Executing {}".format(command[i]))
                self.cus_interface.write(command[i] + b"\n")
                self.cus_interface.read_until(prompt, timeout=20)
        except Exception as e:
            logger.warn("Caught exception while executing commands on cus interface :: {}".format(e))

    def _connect_to_cus_interface(self, host, port, prompt, alias):
        """
        This keyword loads given config file (config_path) on Executor console using Telnet interface.

        Communication to CUS executor console can be done via local ip 127.0.0.1 on port no. 1234 on the setups
        where CUS is available.
        """
        import telnetlib
        cus_interface = None
        try:
            cus_interface = telnetlib.Telnet(host=host, port=port)
            cus_interface.write(b"\n")
            cus_interface.read_until(prompt, timeout=5)
            self.store.add(cus_interface, alias=alias)
        except Exception as e:
            logger.warn("Caught exception while connecting to cus interface :: {}".format(e))
        return cus_interface

    def _data_start(self, profile, profile_params, ue_ids):
        """Keyword to start data traffic from uexgate console. Read the required arguments from profile specified in
        testcase_variable.json file"""
        try:
            self.uexgate.run_uex_command("trf_data_start", ue=self.ue_ids, Mbps=profile_params['bandwidth'],
                                         protocol=profile_params['protocol'], dir=profile_params['direction'],
                                         stats=profile_params.get('stats', "false"))
        except Exception as e:
            raise DataTrafficException("Exception {} during start data traffic for UE:{}".format(e, self.ue_ids))
        self.store.add((ue_ids, profile_params["direction"]), alias=profile)

    def _data_stop(self, profile):
        """Keyword to stop data traffic from uexgate console. Read the required arguments from profile specified in
                testcase_variable.json file"""
        ue_ids, direction = self.store.get(alias=profile)
        try:
            self.uexgate.run_uex_command("trf_data_stop", ue=self.ue_ids, dir=direction)
        except Exception as e:
            raise DataTrafficException("Exception {} during stop data traffic for UE:{}".format(e, self.ue_ids))
        finally:
            self.store.remove(alias=profile)

    def _verify_ue_state(self, ue_id, expected_state):
        """
        Keyword to verify UE state for the give ue_id

        :param string ue_id:
        :param UE_STATE_ENUM expected_state:

        :return: True/False
        :rtype: bool

        """
        try:
            actual_state = self.uexgate.run_uex_command("get_ue_info", id=ue_id)['state']
            if actual_state == expected_state.value:
                return True
            return False
        except Exception as e:
            raise UeIsNotActive("UE-{0} instance exists on UESim, use command ue_dismiss to delete it.\nException:{1}".
                                format(ue_id, str(e)))

    def _load_lua_file_using_egate_terminal(self, device_details):
        lua_files_dict = self._get_lua_file_and_ports(device_details)
        for lua_file, ports in list(lua_files_dict.items()):
            # lua_file = os.path.join(self.relative_cfg_path, lua_file)
            logger.info("lua file path {}".format(lua_file))
            if not os.path.exists(lua_file):
                raise Exception('Lua File {} Does not Exist'.format(lua_file))
            egate_port, edaemon_ports = ports
            self.wtssim.start_wts_applications(egate_port=egate_port, edaemon_ports=edaemon_ports, cfg_file=lua_file)
        self.wtssim.start_wts_services(timeout=self.timeout)

    def call_teardown(self, **kwargs):
        pass

    def execute_cmd_on_egate(self, **kwargs):
        """
            Execute a command on egate and wait for data from the command.

            Many Egate commands are asynchronous. Because of that the data may appear later. This method will execute
            provided command and will wait until some data appears - will ignore any prompt before data.

            :param string  cmd: Command to execute.
            :param int timeout: Timeout for this operation. Default is 10 seconds.
                            Can be specified in human format like 5s, 10minutes, 1min 5s.

            :Supported parameter is available via kwargs:
                * **return_output**   (boolean)  - Flag indicating whether egate log should be printed out. Default is
                                                   True.
                * **pass_regexp**     (string)   - Regexp indicating that the command passed.
                * **fail_regexp**     (string)   - Regexp indicating that the command failed.

            :return: Data from command execution.
            :rtype: string
        """
        cmd = kwargs['cmd']
        # pass_regexp = kwargs.get("pass_regexp", "")
        # fail_regexp = kwargs.get("fail_regexp", "")
        timeout = kwargs.get("timeout", 200)
        return_output = kwargs.get("return_output", True)

        try:
            return self.wtssim.execute_egate_command_and_wait_for_data(cmd, return_output=return_output, timeout=timeout)
        except Exception as e:
            logger.warn("exception in execute command on egate is {}".format(e))
